// ==UserScript==
// @name         Bad Apple Player
// @namespace    bdengine-bad-apple-player
// @version      4.0.0
// @description  Плеер Bad Apple на стене из голов (24×18, 4:3) со звуком
// @author       BDEngine Plugin Helper
// ==/UserScript==

(() => {
    'use strict';

    const NAME = 'Bad Apple Player';
    const WINDOW_ID = 'bdengine-bad-apple-player';
    const log = (...args) => console.log('[Bad Apple Player]', ...args);
    const warn = (...args) => console.warn('[Bad Apple Player]', ...args);
    const error = (...args) => console.error('[Bad Apple Player]', ...args);

    // Стена 4:3: 24 головы в ширину, 18 в высоту. Один блок 8×8 пикселей = одна голова.
    const COLS = 24;
    const ROWS = 18;
    const COUNT = COLS * ROWS;
    const TILE = 8;
    const TILE_PIXELS = TILE * TILE;
    // Лицевая грань головы в текстуре 64×64: x=8, y=8.
    const FACE_X = 8;
    const FACE_Y = 8;
    const WIDTH = COLS * TILE;   // 192
    const HEIGHT = ROWS * TILE;  // 144
    const FRAME_BYTES = WIDTH * HEIGHT / 8;
    const STEP = 0.5;

    // Встроенные данные: видео 192×144, 1 бит на пиксель, zlib + base64; звук AAC (m4a), base64.
    const VIDEO = {
        fps: 12,
        frameCount: 2629,
        data: '',
        audioMime: 'audio/mp4',
        audio: ''
    };

    let api;
    let editor;
    let host = null;
    let root = null;
    let heads = [];
    let canvases = [];
    let contexts = [];
    let frames = null;
    let creating = false;
    let sampleContext;
    let warnedMissingTexture = false;

    // Аудио и часы воспроизведения.
    let audio = null;
    let audioUrl = null;
    let usingAudio = true;
    let playing = false;
    let animationId = 0;
    let fallbackOffset = 0;   // позиция в секундах, если звук недоступен
    let fallbackStart = 0;
    let lastIndex = -1;

    // Что показано на каждой голове (0/1). 2 — ещё не выводилось.
    let shown = new Uint8Array(COUNT * TILE_PIXELS).fill(2);
    const scratch = new Uint8Array(TILE_PIXELS);

    const $ = selector => root?.querySelector(selector);
    const nextFrame = () => new Promise(resolve => requestAnimationFrame(resolve));

    function init() {
        api = window.editorAPI;
        editor = window.editor;

        if (!api) {
            error('editorAPI недоступен.');
            return;
        }

        sampleContext = document.createElement('canvas').getContext('2d');
        api.addButtonDockMenu('icon-image', NAME, openPanel);
        log('Плагин загружен.');
    }

    function base64ToBytes(b64) {
        const raw = atob(b64);
        const bytes = new Uint8Array(raw.length);
        for (let i = 0; i < raw.length; i++) bytes[i] = raw.charCodeAt(i);
        return bytes;
    }

    // Чёрная основа головы: как в импорте изображений редактора.
    // Внешний слой (x 32..63) остаётся прозрачным, поэтому редактор его скрывает.
    function makeBaseCanvas() {
        const canvas = document.createElement('canvas');
        canvas.width = 64;
        canvas.height = 64;
        const ctx = canvas.getContext('2d');
        ctx.fillStyle = '#000';
        ctx.fillRect(0, 0, 32, 16);
        return canvas;
    }

    async function decodeVideo() {
        if (frames) return frames;

        if (typeof DecompressionStream === 'undefined') {
            throw new Error('Эта версия BDEngine не поддерживает DecompressionStream.');
        }

        const stream = new Blob([base64ToBytes(VIDEO.data)])
            .stream()
            .pipeThrough(new DecompressionStream('deflate'));
        const bytes = new Uint8Array(await new Response(stream).arrayBuffer());

        if (bytes.length !== FRAME_BYTES * VIDEO.frameCount) {
            throw new Error('Данные видео повреждены.');
        }

        const list = new Array(VIDEO.frameCount);
        for (let i = 0; i < VIDEO.frameCount; i++) {
            list[i] = bytes.subarray(i * FRAME_BYTES, (i + 1) * FRAME_BYTES);
        }

        frames = list;
        log('Видео декодировано:', frames.length, 'кадров');
        return frames;
    }

    function ensureAudio() {
        if (audio) return audio;

        audioUrl = URL.createObjectURL(new Blob([base64ToBytes(VIDEO.audio)], {type: VIDEO.audioMime}));
        audio = new Audio(audioUrl);
        audio.preload = 'auto';
        audio.addEventListener('ended', () => stop());
        audio.addEventListener('error', () => {
            usingAudio = false;
            warn('Звук не загрузился, воспроизведение пойдёт без него.', audio.error);
            setStatus('Звук недоступен, воспроизведение без звука.');
        });
        return audio;
    }

    function duration() {
        return frames ? frames.length / VIDEO.fps : 0;
    }

    function currentTime() {
        if (usingAudio && audio) return audio.currentTime;
        return fallbackOffset + (performance.now() - fallbackStart) / 1000;
    }

    // Проверка одной головы: какой холст реально привязан и что на нём видно.
    function checkHead(head, canvas, index) {
        const ctx = canvas.getContext('2d', {willReadFrequently: true});
        const face = ctx.getImageData(FACE_X + 4, FACE_Y + 4, 1, 1).data;
        const outerVisible = typeof head.hasHeadAlpha === 'function'
            ? head.hasHeadAlpha(canvas, 1)
            : null;

        const report = {
            index,
            instanced: !!head.isInstancedDisplay,
            paintTexture: !!head.paintTexture,
            hasTempTexture: !!head.tempTexture,
            faceRGBA: [face[0], face[1], face[2], face[3]],
            outerLayerVisible: outerVisible
        };

        if (index === 0) log('Проверка первой головы:', report);

        if (!head.tempTexture) {
            throw new Error(`Голова ${index + 1}: нет tempTexture, обновление кадров невозможно.`);
        }
        if (report.faceRGBA[3] !== 255) {
            warn(`Голова ${index + 1}: лицевая грань не непрозрачна (alpha=${report.faceRGBA[3]}).`);
        }
        if (outerVisible === true) {
            warn(`Голова ${index + 1}: внешний слой виден и может перекрывать пиксели.`);
        }
        return report;
    }

    // Колонка головы col идёт по оси X, а в редакторе ось +X смотрит влево на экране.
    // Поэтому колонка головы col показывает колонку кадра COLS-1-col.
    function sourceColumn(headCol) {
        return COLS - 1 - headCol;
    }

    function setStatus(message) {
        const el = $('#bap-status');
        if (el) el.textContent = message;
    }

    function setDisabled(selector, value) {
        const el = $(selector);
        if (el) el.disabled = value;
    }

    function formatTime(seconds) {
        const s = Math.max(0, Math.floor(seconds));
        const m = Math.floor(s / 60);
        const r = String(s % 60).padStart(2, '0');
        return `${m}:${r}`;
    }

    function updateUI() {
        const total = duration();
        const now = Math.min(currentTime(), total);
        const seek = $('#bap-seek');
        if (seek && total) {
            seek.max = String(total);
            if (document.activeElement !== seek) seek.value = String(now);
        }
        const time = $('#bap-time');
        if (time) time.textContent = `${formatTime(now)} / ${formatTime(total)}`;
        const playBtn = $('#bap-play');
        if (playBtn) playBtn.textContent = playing ? '❚❚' : '▶';
        setDisabled('#bap-play', heads.length !== COUNT || !frames);
    }

    async function createWall() {
        if (creating) return;
        if (heads.length === COUNT) {
            setStatus('Стена уже создана.');
            return;
        }

        creating = true;
        setDisabled('#bap-create', true);

        const baseCanvas = makeBaseCanvas();
        const created = [];
        const newCanvases = [];

        try {
            for (let i = 0; i < COUNT; i++) {
                const head = await api.add('player_head', 'ItemDisplay', null, false);

                if (!head) throw new Error(`Не создана голова ${i + 1}.`);

                if (typeof head.setPosition !== 'function' ||
                    typeof head.setScale !== 'function' ||
                    typeof head.setTexture !== 'function' ||
                    typeof head.getPaintTexture !== 'function') {
                    throw new Error('У объекта нет нужного API текстуры/позиции.');
                }

                // Отдельный базовый холст: setTexture очищает целевой холст,
                // поэтому передавать сам холст головы нельзя.
                head.setTexture(baseCanvas, true, true);

                const canvas = head.getPaintTexture();
                if (!canvas || canvas.width !== 64 || canvas.height !== 64) {
                    throw new Error(`Голова ${i + 1}: не получен холст 64×64.`);
                }

                if (i === 0) checkHead(head, canvas, 0);
                else if (!head.tempTexture) {
                    throw new Error(`Голова ${i + 1}: нет tempTexture.`);
                }

                created.push(head);
                newCanvases.push(canvas);

                if ((i + 1) % 16 === 0) {
                    setStatus(`Создание: ${i + 1}/${COUNT}`);
                    await nextFrame();
                }
            }

            heads = created;
            canvases = newCanvases;
            contexts = canvases.map(c => c.getContext('2d', {willReadFrequently: true}));
            shown = new Uint8Array(COUNT * TILE_PIXELS).fill(2);
            warnedMissingTexture = false;

            arrange();
            refreshEditor();

            setStatus(`Создано ${heads.length} голов.`);
            log('Стена создана:', heads.length);
        } catch (err) {
            heads = created;
            canvases = newCanvases;
            contexts = canvases.map(c => c.getContext('2d', {willReadFrequently: true}));
            setStatus(`Ошибка создания: ${err.message}\nСоздано: ${created.length}/${COUNT}`);
            error(err);
        } finally {
            creating = false;
            setDisabled('#bap-create', false);
            updateUI();
        }
    }

    // Стена 24×18: голова (col,row) стоит в точке, которую задают её колонка и строка.
    function arrange() {
        if (!heads.length) {
            setStatus('Сначала создай стену.');
            return;
        }

        heads.forEach((head, i) => {
            const col = i % COLS;
            const row = Math.floor(i / COLS);
            head.setPosition({
                x: (col - (COLS - 1) / 2) * STEP,
                y: ((ROWS - 1) / 2 - row) * STEP,
                z: 0
            });
        });

        // Внутренний API редактора (editor.group): может измениться в будущих версиях.
        try {
            if (editor && typeof editor.group === 'function' && !editor.__badAppleGroupCreated) {
                heads.forEach(head => { head.selected = true; });
                editor.group();
                editor.__badAppleGroupCreated = true;
            }
        } catch (err) {
            warn('Группировка не удалась:', err);
        }

        refreshEditor();
        setStatus('Стена расставлена.');
    }

    function applyFrame(packed) {
        const changed = [];

        for (let i = 0; i < COUNT; i++) {
            const col = i % COLS;
            const row = (i - col) / COLS;
            const srcCol = sourceColumn(col);
            const base = i * TILE_PIXELS;
            let diff = 0;

            for (let py = 0; py < TILE; py++) {
                const rowStart = (row * TILE + py) * WIDTH + srcCol * TILE;
                for (let px = 0; px < TILE; px++) {
                    const pixel = rowStart + px;
                    const bit = (packed[pixel >> 3] >> (7 - (pixel & 7))) & 1;
                    const k = py * TILE + px;
                    scratch[k] = bit;
                    if (shown[base + k] !== bit) diff++;
                }
            }

            if (diff === 0) continue;

            shown.set(scratch, base);
            changed.push(i);
        }

        if (!changed.length) return;

        const tileImage = sampleContext.createImageData(TILE, TILE);
        const data = tileImage.data;

        for (const i of changed) {
            const head = heads[i];
            const ctx = contexts[i];
            if (!head || !ctx) continue;

            const base = i * TILE_PIXELS;
            for (let k = 0; k < TILE_PIXELS; k++) {
                const value = shown[base + k] ? 255 : 0;
                const o = k * 4;
                data[o] = value;
                data[o + 1] = value;
                data[o + 2] = value;
                data[o + 3] = 255;
            }
            ctx.putImageData(tileImage, FACE_X, FACE_Y);

            if (head.tempTexture) {
                head.tempTexture.needsUpdate = true;
            } else if (!warnedMissingTexture) {
                warnedMissingTexture = true;
                warn('У головы нет tempTexture: кадры не будут видны.');
            }
        }

        // Внутренний метод редактора: перерисовка сцены по требованию.
        editor?.render?.();
    }

    function showFrameAt(seconds) {
        if (!frames || heads.length !== COUNT) return;
        const index = Math.min(frames.length - 1, Math.max(0, Math.floor(seconds * VIDEO.fps)));
        lastIndex = index;
        applyFrame(frames[index]);
    }

    function tick() {
        if (!playing) return;

        const t = currentTime();
        if (t >= duration()) {
            stop();
            return;
        }

        const index = Math.min(frames.length - 1, Math.floor(t * VIDEO.fps));
        if (index !== lastIndex) {
            lastIndex = index;
            applyFrame(frames[index]);
        }

        updateUI();
        animationId = requestAnimationFrame(tick);
    }

    async function play() {
        if (playing) return;
        if (heads.length !== COUNT) {
            setStatus('Сначала создай стену.');
            return;
        }
        if (!frames) {
            setStatus('Видео ещё декодируется.');
            return;
        }

        const a = ensureAudio();
        if (usingAudio) {
            try {
                await a.play();
            } catch (err) {
                usingAudio = false;
                warn('Не удалось запустить звук:', err);
            }
        }

        if (!usingAudio) {
            fallbackStart = performance.now();
        }

        playing = true;
        setStatus('Воспроизведение.');
        animationId = requestAnimationFrame(tick);
        updateUI();
    }

    function pause() {
        if (!playing && !(audio && !audio.paused)) return;
        playing = false;
        if (audio) audio.pause();
        if (!usingAudio) {
            fallbackOffset = currentTime();
        }
        cancelAnimationFrame(animationId);
        animationId = 0;
        updateUI();
    }

    function stop() {
        pause();
        if (audio) audio.currentTime = 0;
        fallbackOffset = 0;
        lastIndex = -1;
        showFrameAt(0);
        updateUI();
    }

    function togglePlay() {
        if (playing) pause();
        else play();
    }

    function seek(seconds) {
        if (audio) audio.currentTime = seconds;
        fallbackOffset = seconds;
        fallbackStart = performance.now();
        lastIndex = -1;
        showFrameAt(seconds);
        updateUI();
    }

    // Стили живут внутри Shadow DOM. :host сбрасывает все унаследованные свойства,
    // поэтому шрифты и цвета редактора не влияют на плеер, и наоборот.
    // Палитра и скругления взяты из стилей редактора BDEngine:
    // фон панелей #1e1e1e, рамка #212121, акцент #ff9900, шрифт Montserrat.
    const STYLE = `
        :host {
            all: initial;
            position: fixed;
            right: 24px;
            bottom: 24px;
            z-index: 2147483000;
            width: 300px;
            font-family: Montserrat, system-ui, sans-serif;
            font-size: 13px;
            color: #ffffffc9;
        }
        * { box-sizing: border-box; font-family: inherit; }
        .panel {
            background: #1e1e1e;
            border: solid 1px #212121;
            border-radius: 8px;
            padding: 12px;
            box-shadow: 0 10px 30px rgba(0, 0, 0, .5);
            user-select: none;
        }
        .head {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 10px;
            cursor: move;
            touch-action: none;
        }
        .label { color: #f90; text-transform: uppercase; font-size: 11px; letter-spacing: .04em; font-weight: 600; }
        .sub { color: #858585; font-size: 11px; margin-top: 2px; }
        .actions { display: flex; gap: 6px; align-items: center; }
        button {
            cursor: pointer;
            color: #f90;
            background: #ff99001a;
            border: solid 1px #ff9900;
            border-radius: 20px;
            font: inherit;
            font-size: 12px;
            padding: 5px 12px;
        }
        button:hover:not(:disabled) { background: #ff990033; }
        button:disabled { opacity: .4; cursor: default; }
        .icon {
            width: 28px;
            height: 28px;
            padding: 0;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
        }
        .box {
            background: #181818;
            border: solid 1px #ffffff0d;
            border-radius: 6px;
            padding: 10px;
        }
        .controls { display: flex; gap: 8px; align-items: center; justify-content: center; margin-bottom: 8px; }
        .play { width: 44px; height: 44px; padding: 0; border-radius: 50%; font-size: 16px; }
        input[type=range] { width: 100%; accent-color: #ff9900; }
        .meta { display: flex; justify-content: space-between; align-items: center; margin-top: 8px; color: #858585; font-size: 11px; }
        .vol { display: flex; align-items: center; gap: 6px; }
        .vol input { width: 80px; }
        .status { color: #858585; font-size: 11px; margin: 10px 0 0; min-height: 14px; white-space: pre-wrap; }
    `;

    // События внутри панели не уходят в редактор: иначе горячие клавиши,
    // орбита камеры и колесо мыши срабатывали бы во время управления плеером.
    const ISOLATED_EVENTS = [
        'pointerdown', 'pointermove', 'pointerup', 'pointercancel',
        'mousedown', 'mouseup', 'mousemove', 'click', 'dblclick',
        'wheel', 'contextmenu', 'keydown', 'keyup', 'keypress',
        'touchstart', 'touchmove', 'touchend'
    ];

    function openPanel() {
        if (host) {
            host.style.display = 'block';
            updateUI();
            return;
        }

        // Удаляем остаток от предыдущей загрузки плагина, если он есть.
        document.getElementById('bdengine-bad-apple-host')?.remove();

        host = document.createElement('div');
        host.id = 'bdengine-bad-apple-host';
        document.body.appendChild(host);
        root = host.attachShadow({mode: 'closed'});

        for (const type of ISOLATED_EVENTS) {
            host.addEventListener(type, event => event.stopPropagation());
        }

        root.innerHTML = `
        <style>${STYLE}</style>
        <div class="panel">
            <div class="head" id="bap-drag">
                <div>
                    <div class="label">Bad Apple</div>
                    <div class="sub">Стена ${COLS}×${ROWS} · ${COUNT} голов · ${VIDEO.fps} FPS</div>
                </div>
                <div class="actions">
                    <button id="bap-create">Создать</button>
                    <button class="icon" id="bap-close" title="Закрыть">✕</button>
                </div>
            </div>

            <div class="box">
                <div class="controls">
                    <button class="play" id="bap-play" disabled>▶</button>
                    <button class="icon" id="bap-stop" title="Стоп">■</button>
                </div>
                <input id="bap-seek" type="range" min="0" max="1" step="0.01" value="0">
                <div class="meta">
                    <span id="bap-time">0:00 / 0:00</span>
                    <label class="vol">Звук <input id="bap-volume" type="range" min="0" max="100" value="80"></label>
                </div>
            </div>

            <p class="status" id="bap-status"></p>
        </div>`;

        // Перетаскивание за заголовок, в пределах окна браузера.
        const handle = root.querySelector('#bap-drag');
        let drag = null;

        handle.addEventListener('pointerdown', event => {
            if (event.target.closest('button')) return;
            const rect = host.getBoundingClientRect();
            drag = {dx: event.clientX - rect.left, dy: event.clientY - rect.top};
            handle.setPointerCapture(event.pointerId);
        });
        handle.addEventListener('pointermove', event => {
            if (!drag) return;
            const left = Math.min(Math.max(0, event.clientX - drag.dx), window.innerWidth - host.offsetWidth);
            const top = Math.min(Math.max(0, event.clientY - drag.dy), window.innerHeight - host.offsetHeight);
            host.style.left = `${left}px`;
            host.style.top = `${top}px`;
            host.style.right = 'auto';
            host.style.bottom = 'auto';
        });
        const endDrag = () => { drag = null; };
        handle.addEventListener('pointerup', endDrag);
        handle.addEventListener('pointercancel', endDrag);

        $('#bap-create').addEventListener('click', createWall);
        $('#bap-close').addEventListener('click', closePanel);
        $('#bap-play').addEventListener('click', togglePlay);
        $('#bap-stop').addEventListener('click', stop);
        $('#bap-seek').addEventListener('input', event => seek(Number(event.target.value)));
        $('#bap-volume').addEventListener('input', event => {
            ensureAudio().volume = Number(event.target.value) / 100;
        });

        ensureAudio();
        audio.volume = 0.8;

        setStatus(frames ? 'Видео готово. Создай стену.' : 'Загрузка видео…');
        decodeVideo()
            .then(() => {
                setStatus(heads.length === COUNT ? 'Готово к воспроизведению.' : 'Видео готово. Создай стену.');
                updateUI();
            })
            .catch(err => {
                error(err);
                setStatus(`Ошибка видео: ${err.message}`);
            });

        if (heads.length === COUNT) setDisabled('#bap-create', true);
        updateUI();
    }

    function closePanel() {
        pause();
        if (host) host.style.display = 'none';
    }

    function refreshEditor() {
        // Внутренние свойства редактора: могут измениться в будущих версиях.
        editor?.objects?.updateMatrixWorld?.(true);
        editor?.meshManager?.updateDirty?.();
        api.update(true);
        editor?.render?.();
    }

    // Редактор отправляет 'bde:started' после создания GUI (dockbar уже готов).
    window.addEventListener('bde:started', init, {once: true});
})();
